"use client";

import * as React from "react";
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";

import { cn } from "@/lib/utils";
import { cardSlab, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Accordion: a stack of questions on one white card with a 1rem corner. */
const Accordion = React.forwardRef<HTMLDivElement, WithClassName<AccordionPrimitive.Root.Props>>(
  ({ className, ...props }, ref) => (
    <AccordionPrimitive.Root
      ref={ref}
      data-slot="accordion"
      className={cn("w-full rounded-3xl px-6", cardSlab, className)}
      {...props}
    />
  ),
);
Accordion.displayName = "Accordion";

/** One row of the accordion, divided from the next by a faint hairline. */
const AccordionItem = React.forwardRef<HTMLDivElement, WithClassName<AccordionPrimitive.Item.Props>>(
  ({ className, ...props }, ref) => (
    <AccordionPrimitive.Item
      ref={ref}
      data-slot="accordion-item"
      className={cn("border-b border-border last:border-b-0", className)}
      {...props}
    />
  ),
);
AccordionItem.displayName = "AccordionItem";

/** The question in medium weight, with an arrow at the end that turns over as the answer opens. */
const AccordionTrigger = React.forwardRef<HTMLButtonElement, WithClassName<AccordionPrimitive.Trigger.Props>>(
  ({ className, children, ...props }, ref) => (
    <AccordionPrimitive.Header data-slot="accordion-header" className="flex">
      <AccordionPrimitive.Trigger
        ref={ref}
        data-slot="accordion-trigger"
        className={cn(
          "group/trigger flex flex-1 items-center justify-between gap-3 rounded-md py-4 text-start",
          "text-base font-medium text-foreground",
          focusRing,
          "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
          className,
        )}
        {...props}
      >
        {children}
        <ChevronDownIcon
          aria-hidden="true"
          className="size-4 shrink-0 text-muted-foreground transition-transform duration-base ease-(--ease-out) group-data-[panel-open]/trigger:rotate-180"
        />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  ),
);
AccordionTrigger.displayName = "AccordionTrigger";

/** The answer in muted text, growing to its measured height as it opens. */
const AccordionContent = React.forwardRef<HTMLDivElement, WithClassName<AccordionPrimitive.Panel.Props>>(
  ({ className, children, ...props }, ref) => (
    <AccordionPrimitive.Panel
      ref={ref}
      data-slot="accordion-content"
      className={cn(
        "h-(--accordion-panel-height) overflow-hidden text-sm leading-relaxed text-muted-foreground",
        "transition-[height] duration-base ease-(--ease-out)",
        "data-[starting-style]:h-0 data-[ending-style]:h-0",
      )}
      {...props}
    >
      <div className={cn("pb-4", className)}>{children}</div>
    </AccordionPrimitive.Panel>
  ),
);
AccordionContent.displayName = "AccordionContent";

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

// Iconoir, the icon library this system pairs with, drawn inline
// so the installed component loads no icon at runtime:
// "iconoir:nav-arrow-down"
// [BD-1029]
function ChevronDownIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="m6 9l6 6l6-6"/>
    </svg>
  );
}
